<script setup lang="ts">
import { onMounted, ref, watch } from 'vue'
import { ArrowUpRight, ClipboardList, Plus, CircleCheck, Circle } from 'lucide-vue-next'
import { api, dateLabel, messageOf, projectName, taskStatuses } from '../api'
import type { Attachment, Today } from '../types'
import RecordTimeline from '../components/RecordTimeline.vue'
const props=defineProps<{revision:number}>();const emit=defineEmits<{record:[];navigate:[page:string];image:[a:Attachment]}>()
const data=ref<Today>();const error=ref('');const loading=ref(false)
async function load(){loading.value=true;error.value='';try{data.value=await api<Today>('/api/today')}catch(e){error.value=messageOf(e)}finally{loading.value=false}}
onMounted(load);watch(()=>props.revision,load)
</script>
<template><div class="page-heading"><div><p class="page-date">{{data?.date||'本地工作空间'}}</p><h1>今日工作台</h1><p class="page-description">把待办安排好，把现场的事记下来。</p></div><button class="button primary" @click="emit('record')"><Plus :size="18"/>记一条</button></div><div v-if="error" class="error-banner" role="alert">{{error}}<button class="text-button" @click="load">重试</button></div><p v-if="loading&&!data" class="loading-message">正在读取今日工作…</p><template v-if="data"><div class="today-facts"><span><b>{{data.stats.projects}}</b> 个项目</span><span><b>{{data.stats.tasks_open}}</b> 项待办</span><span><b>{{data.stats.issues_open}}</b> 个待处理问题</span><span><b>{{data.stats.records_today}}</b> 条今日记录</span><span v-if="data.stats.unclassified" class="unclassified">{{data.stats.unclassified}} 条记录待归类</span></div><div class="welcome-strip" v-if="data.stats.projects===0"><div class="welcome-icon"><ClipboardList :size="26"/></div><div><h2>从第一个项目开始</h2><p>建立项目后，任务、现场记录和问题就能串在一起。也可以先随手记下想法。</p></div><button class="button" @click="emit('navigate','projects')">新建项目<ArrowUpRight :size="16"/></button></div><div class="dashboard-columns"><section class="surface"><div class="section-heading"><h2>待办工作 <span class="count">{{data.tasks.length}}</span></h2><button class="text-button" @click="emit('navigate','tasks')">全部任务<ArrowUpRight :size="14"/></button></div><div v-if="!data.tasks.length" class="empty-state compact"><CircleCheck :size="32"/><h3>当前没有待办任务</h3><p>在项目中拆分工作，安排负责人和计划日期。</p><button class="button subtle small" @click="emit('navigate','tasks')">管理任务</button></div><div v-else class="today-task-list"><button class="today-task" v-for="task in data.tasks" :key="task.id" @click="emit('navigate','tasks')"><Circle :size="18" class="task-circle"/><div><h3>{{task.name}}</h3><p>{{projectName(task.project_id)}} <span v-if="task.assignee">／ {{task.assignee}}</span></p></div><div class="task-trailing"><span class="badge" :class="task.status">{{taskStatuses[task.status]}}</span><span :class="{overdue:task.overdue}">{{task.plan_end?(task.overdue?'已逾期 · ':'到期 ')+dateLabel(task.plan_end):'未设日期'}}</span></div></button></div></section><section class="surface"><div class="section-heading"><h2>今日记录 <span class="count">{{data.stats.records_today}}</span></h2><button class="text-button" @click="emit('navigate','records')">时间线<ArrowUpRight :size="14"/></button></div><div class="timeline-wrap"><RecordTimeline v-if="data.records.length" :records="data.records" @image="emit('image',$event)"/><div v-else class="empty-state compact"><div class="empty-timeline"><i/><i/><i/></div><h3>今天的故事，还没开始记录</h3><p>巡检、讨论、发现或决定，都值得留下一笔。</p><button class="button subtle small" @click="emit('record')">写下第一条记录</button></div></div></section></div><div class="workspace-note"><span class="local-dot"/>本机保存，记录随手可查。<button class="text-button" @click="emit('navigate','settings')">管理备份</button></div></template></template>
